// middleware/adminOnly.js
//
// Use AFTER `protect` (it needs req.user). Allows only the user IDs listed in
// the ADMIN_USER_IDS env var (comma-separated), e.g.
//
//   ADMIN_USER_IDS=3f2a9c1e-5b7d-4e8a-9c21-7d4e5f6a8b90,<another id>
//
// IDs, not emails, on purpose: email/password signup does not verify email
// addresses yet, so anyone could register an account using an admin's email
// address if that admin hadn't signed up with it. A user ID is generated by
// the database and cannot be chosen by an attacker.
//
// Fails CLOSED: if ADMIN_USER_IDS is empty or unset, nobody is an admin.

function parseAdminIds(raw) {
  return new Set(
    String(raw || "")
      .split(",")
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean),
  );
}

function adminOnly(req, res, next) {
  const admins = parseAdminIds(process.env.ADMIN_USER_IDS);
  const userId = req.user && req.user.id ? String(req.user.id).toLowerCase() : null;

  if (!userId || !admins.has(userId)) {
    return res.status(403).json({
      message: "You don't have permission to access this.",
      code: "FORBIDDEN",
      severity: "error",
    });
  }

  return next();
}

module.exports = { adminOnly, parseAdminIds };
